    """Return index of highest-priority tier whose keyword appears, else -1."""
    for tier_idx, kws in enumerate(KEYWORD_TIERS):
        for kw in kws:
            if kw in line_up:
                return tier_idx
    return -1


def last_number(text):
    matches = NUM_RE.findall(text)
    if not matches:
        return None
    return float(matches[-1].replace(",", ""))


def find_totals_from_text(text):
    """Return list of (tier_index, value) candidates from a single OCR variant."""
    candidates = []
    lines = [ln.rstrip() for ln in text.splitlines()]
    n = len(lines)
    for i, line in enumerate(lines):
        line_up = line.upper()
        if not line_up.strip():
            continue
        tier_idx = match_tier(line_up)
        if tier_idx < 0:
            continue
        # For generic TOTAL/AMOUNT tier, apply exclusion filter.
        if tier_idx == 3 and line_has_exclusion(line_up):
            continue

        val = last_number(line)
        if val is not None:
            candidates.append((tier_idx, val))
            continue

        # Two-line fallback: only when the keyword line has NO digits at all.
        if not re.search(r"\d", line):
            for j in range(i + 1, n):
                nxt = lines[j].strip()
                if not nxt:
                    continue
                # Do not fall through into an obvious excluded line.
                if tier_idx == 3 and line_has_exclusion(nxt.upper()):
                    break
                nxt_val = last_number(nxt)
                if nxt_val is not None:
                    candidates.append((tier_idx, nxt_val))
                break
    return candidates


def aggregate(all_variant_candidates):
