        if not line_up.strip():
            continue
        tier_idx = match_tier(line_up)
        if tier_idx < 0:
            continue
        # For generic TOTAL/AMOUNT tier, apply exclusion filter.
        if tier_idx == 3 and line_has_exclusion(line_up):
            continue

